func TestTextMigrationLockKeysMatchIndependentXXH3Vectors(t *testing.T) {
	// Independent libxxhash.so.0 XXH3_64bits vectors, not generated by Go.
	for value, want := range map[string]uint64{
		"":                                       3244421341483603138,
		"wire-server:arbiter-migrations:arbiter": 14219464709246170394,
		"example.com":                            10044734154400447347,
		"Straße.example":                         2182970386891305697,
		"mls":                                    5000805854559750088,
		strings.Repeat("a", 253):                 15375750549016112149,
	} {
		if uint64(textMigrationLockKey(value)) != want {
			t.Fatal("shared native text lock hash changed")
		}
	}
	if foldedDomainKey("Straße.EXAMPLE") != "strasse.example" {
		t.Fatal("DomainKey uses full case folding, not ASCII lowercase")
	}
}

type observedDomainMigrationStore struct {
	calls     []string
	exists    bool
	locked    bool
	lockError error
	written   *domainRegistrationMigrationRow
	block     bool
}

func (s *observedDomainMigrationStore) withDomainLock(_ context.Context, domain string, action func() error) error {
	s.calls = append(s.calls, "lock:"+domain)
	if s.lockError != nil {
		return s.lockError
	}
	s.locked = true
	defer func() { s.locked = false; s.calls = append(s.calls, "unlock") }()
	return action()
}
func (s *observedDomainMigrationStore) domainExists(ctx context.Context, _ string) (bool, error) {
	if !s.locked {
		return false, errors.New("missing native exclusive lock")
	}
	s.calls = append(s.calls, "exists")
	if s.block {
		<-ctx.Done()
		return false, ctx.Err()
	}
	return s.exists, nil
}
func (s *observedDomainMigrationStore) writeDomain(_ context.Context, row domainRegistrationMigrationRow) error {
	if !s.locked {
		return errors.New("missing native exclusive lock")
	}
	s.calls = append(s.calls, "write")
	s.written = &row
	return nil
}

func TestDomainMigrationRereadsUnderLockAndKeepsExistingPGOrDeletedCassandraRows(t *testing.T) {
	for _, variant := range []string{"current", "already-migrated", "deleted"} {
		s := testMigrationService(time.Second)
		store := &observedDomainMigrationStore{exists: variant == "already-migrated"}
		counted, err := s.copyDomainRegistration(t.Context(), migrationRow{"domain": "Example.COM", "domain_redirect": int32(1)}, store, func(_ context.Context, domain string) (*domainRegistrationMigrationRow, error) {
			if !store.locked || domain != "example.com" {
				t.Fatal("reread outside source lock or folded key lost")
			}
			store.calls = append(store.calls, "read-current")
			if variant == "deleted" {
				return nil, nil
			}
			row, err := decodeDomainRegistrationMigration(migrationRow{"domain": "Example.COM", "domain_redirect": int32(6)})
			return &row, err
		})
		want := []string{"lock:example.com", "exists"}
		if variant != "already-migrated" {
			want = append(want, "read-current")
		}
		if variant == "current" {
			want = append(want, "write")
		}
		want = append(want, "unlock")
		if err != nil || counted != (variant == "current") || !reflect.DeepEqual(store.calls, want) {
			t.Fatalf("source domain %s ordering changed: %v %v", variant, store.calls, err)
		}
		if counted && store.written.Values[1] != int32(6) {
			t.Fatal("stale scan value overwrote live Cassandra row")
		}
		if s.migrations["domain_registration"].observations["success"].count != 1 {
			t.Fatal("successful skipped domain lock not observed")
		}
	}
}

func TestDomainMigrationSeparatesLockTimeoutFromFatalRowTimeout(t *testing.T) {
	for _, lockTimeout := range []bool{true, false} {
		s := testMigrationService(10 * time.Millisecond)
		store := &observedDomainMigrationStore{block: !lockTimeout}
		if lockTimeout {
			store.lockError = &migrationLockTimeout{}
		}
		_, err := s.copyDomainRegistration(t.Context(), migrationRow{"domain": "example.com"}, store, func(context.Context, string) (*domainRegistrationMigrationRow, error) {
			t.Fatal("failed lock/timeout read data")
			return nil, nil
		})
		if err == nil {
			t.Fatal("failed lock/timeout accepted")
		}
		var lock *migrationLockTimeout
		if errors.As(err, &lock) != lockTimeout {
			t.Fatal("fatal row timeout changed into retriable lock timeout")
		}
		outcome := "timeout"
		if lockTimeout {
			outcome = "lock_timeout"
		}
		if s.migrations["domain_registration"].observations[outcome].count != 1 {
			t.Fatal("native lock outcome missing")
		}
	}
}

func TestDomainMigrationPhasesRescanTogetherAndChallengesHaveNoRowTimeout(t *testing.T) {
	s := testMigrationService(10 * time.Millisecond)
	first, second := 0, 0
	page := func(context.Context, []byte, int) ([]migrationRow, []byte, error) {
		return []migrationRow{{}}, nil, nil
	}
	err := s.migratePhases(t.Context(), "domain_registration", []migrationPhase{
		{page: page, write: func(ctx context.Context, _ migrationRow) (bool, error) {
			first++
			if _, deadline := ctx.Deadline(); deadline {
				t.Fatal("native challenge unexpectedly given row timeout")
			}
			return true, nil
		}},
		{page: page, write: func(context.Context, migrationRow) (bool, error) {
			second++
			if second == 1 {
				return false, &migrationLockTimeout{}
			}
			return true, nil
		}},
	})
	m := s.migrations["domain_registration"]
	if err != nil || first != 2 || second != 2 || m.finished != 1 || m.failed != 0 || m.migrated != 3 || len(m.observations) != 0 {
		t.Fatal("source combined phase retry/counters changed")
	}
}

func TestDomainChallengeMigrationPreservesTypedExpiryAndBoundTokens(t *testing.T) {
	id, _ := gocql.ParseUUID(jobUUID)
	row := migrationRow{"id": id, "domain": "EXAMPLE.com", "challenge_token_hash": []byte("synthetic hash"), "dns_verification_token": "synthetic_token==", "ttl(challenge_token_hash)": int32(120)}
	calls := 0
	write := func(_ context.Context, sql string, args ...any) error {
		calls++
		if len(args) != 5 || args[1] != "example.com" || args[4] != int32(120) || strings.Contains(sql, "synthetic") {
			t.Fatal("challenge TTL/domain/bound tokens changed")
		}
		return nil
	}
	if counted, err := copyDomainChallenge(t.Context(), row, write); err != nil || !counted {
		t.Fatal("valid challenge rejected")
	}
	row["ttl(challenge_token_hash)"] = int32(0)
	if counted, err := copyDomainChallenge(t.Context(), row, write); err != nil || counted || calls != 1 {
		t.Fatal("expired challenge copied")
	}
	row["dns_verification_token"] = "invalid+token"
	if _, err := decodeDomainChallengeMigration(row); err == nil {
		t.Fatal("native DNS token alphabet not enforced")
	}
	row["domain"] = "invalid dotless"
	if _, err := decodeDomainChallengeMigration(row); err == nil {
		t.Fatal("challenge Domain validation bypassed")
	}
}

func TestDomainRegistrationDecodesStoredTagsNullableFieldsAndURLs(t *testing.T) {
	for _, row := range []migrationRow{{"domain": "legacy dotless"}, {"domain": "Example.COM", "domain_redirect": int32(6), "team_invite": int32(3), "backend_url": []byte("https://example.com/%41?x=%42#%43"), "dns_verification_token": "a=b"}} {
		if _, err := decodeDomainRegistrationMigration(row); err != nil {
			t.Fatal("source valid stored row rejected")
		}
	}
	for _, column := range []string{"domain_redirect", "team_invite", "idp_id", "ownership_token_hash", "dns_verification_token", "backend_url"} {
		row := migrationRow{"domain": "example.com", column: "invalid synthetic field"}
		if _, err := decodeDomainRegistrationMigration(row); err == nil {
			t.Fatal("native stored field validation missing")
		}
	}
	for _, value := range []string{"http://example.com", "https://example.com/invalid space"} {
		if _, err := decodeDomainRegistrationMigration(migrationRow{"domain": "example.com", "backend_url": []byte(value)}); err == nil {
			t.Fatal("invalid stored HTTPS URL accepted")
		}
	}
}

func TestStoredHTTPSURLsUseNativeSerialization(t *testing.T) {
	cases := map[string]string{
		"https://EXAMPLE.com:00443/%41+a%2Fb?x=%42&flag&=ignored&&x=+%2f#%43": "https://EXAMPLE.com:443/A%20a/b?x=B&flag=&x=%20%2F#%43",
		"https://example.com/%zz?bad=%zz":                                     "https://example.com/%25zz?bad=%25zz",
		"https://user@example.com":                                            "https://user:@example.com",
		"https://[2001:db8::1]:443/a":                                         "https://2001:db8::1:443/a",
		"https://example.com/?":                                               "https://example.com/",
	}
	for input, want := range cases {
		got, err := storedHTTPSURL([]byte(input))
		if err != nil || string(got) != want {
			t.Fatalf("native URI serialization changed: %s %v", got, err)
		}
	}
}
